for (const row of Object.values(ULTRASOUND_REPORT_PATTERNS).flat()) {
  row.appearance = ULTRASOUND_APPEARANCE_DETAILS[row.id] ?? row.meaning;
  row.books = ['BSAVA Manual of Canine and Feline Ultrasonography'];
}
ULTRASOUND_REPORT_PATTERNS.liver[0].mechanism = 'O aparelho envia pulsos e recebe ecos das diferenças de impedância acústica entre estruturas. No parênquima, muitos refletores menores que a resolução produzem dispersão; a interferência dos ecos gera a granulação (speckle), que não é uma fotografia de cada célula. Fibrose, nódulos regenerativos e infiltração podem mudar a distribuição dessas interfaces e criar textura irregular, mas frequência, foco, ganho e resolução também mudam a aparência. Gordura e outras alterações celulares podem coexistir. Portanto, “grosseiro” descreve o padrão dos ecos, sem confirmar fibrose ou indicar sozinho a gravidade.';

for (const organ of Object.keys(ULTRASOUND_EXTENDED_PATTERNS) as UltrasoundOrganId[]) {
  ULTRASOUND_REPORT_PATTERNS[organ].push(...ULTRASOUND_EXTENDED_PATTERNS[organ].map((row, index) => ({ ...row, id: `${organ}-extended-${index}`, pages: '', species: row.species ?? ['dog', 'cat'] })));
}

export const ULTRASOUND_PHYSICS_GUIDE = [
  { term: 'Hiperecogênico / hipoecogênico', explanation: 'Mais claro / mais escuro que uma referência. O brilho representa a amplitude dos ecos recebidos; depende das interfaces, profundidade e ajustes. Não significa sozinho tecido “mais denso” nem uma doença específica.', pages: '2–6' },
  { term: 'Anecoico / reforço posterior', explanation: 'Líquido simples costuma retornar poucos ecos e atenuar menos o feixe. Tecidos atrás dele parecem mais claros; esse reforço é um efeito acústico e não doença do tecido posterior.', pages: '8' },
  { term: 'Grosseiro / granular / heterogêneo', explanation: 'A granulação decorre da dispersão dos ecos nas interfaces do parênquima. “Grosseiro” descreve a textura; “heterogêneo”, sua falta de uniformidade. Resolução e ajustes interferem, e nenhum dos termos identifica histologia.', pages: '3–6' },
  { term: 'Sombra acústica', explanation: 'O feixe é refletido ou atenuado e poucos ecos chegam de regiões além do foco. Mineral, osso e gás podem produzi-la; sombra de borda também pode resultar de refração em uma superfície curva.', pages: '7–8' },
  { term: 'Reverberação / cauda de cometa', explanation: 'Reflexões repetidas fazem ecos aparecerem mais profundos que a interface real. É comum junto a gás ou refletores fortes; o artefato não identifica por si só uma infecção.', pages: '6–7' },
  { term: 'Pseudossedimento / ecos falsos no líquido', explanation: 'Lóbulos laterais e espessura do feixe podem colocar ecos da parede dentro do lúmen. Mudar plano, foco e ganho ajuda a distinguir artefato de conteúdo real.', pages: '8–9' },
  { term: 'Sem fluxo no Doppler', explanation: 'Pode haver pouca perfusão, mas ângulo próximo de 90°, ajustes inadequados e fluxo lento também impedem a detecção. Ausência de cor não comprova avascularidade, necrose ou torção.', pages: '9' },
  { term: 'Imagem em espelho', explanation: 'Uma superfície muito refletora, como o diafragma, prolonga o trajeto dos ecos e faz o aparelho posicionar uma cópia em local falso. Não concluir hérnia apenas por uma aparente estrutura além do diafragma.', pages: '7' },
];

const normalize = (text: string) => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('pt-BR');
export function getUltrasoundReportPatterns(organ: UltrasoundOrganId, species: UltrasoundSpecies, query = '') {
  const terms = normalize(query).trim().split(/\s+/).filter(Boolean);
  return ULTRASOUND_REPORT_PATTERNS[organ].filter(row => row.species.includes(species) && terms.every(term => normalize([row.term, row.meaning, row.appearance, row.mechanism, row.differentials, row.consider, ...getUltrasoundDifferentialExplanations(organ, row.differentials, species).map(item => `${item.name} ${item.pathophysiology} ${item.appearance} ${item.clinical}`)].join(' ')).includes(term)));
}

export function ultrasoundPatternSource(pages: string) {
  const pdf = pages.split(';').map(range => range.trim().split('–').map(page => Number(page) + 12).join('–')).join('; ');
  return `BSAVA Ultrasonography, 1ª ed. · p. ${pages} · PDF ${pdf}`;
}
